const body = $input.first().json.body;
const keepList = (body.keep_spots || []).join('、');
const regionNote = body.region ? `，優先推薦 ${body.region} 附近的地點` : '';
const slotLabel = body.slot === 'morning' ? '早上' : body.slot === 'afternoon' ? '下午' : '晚上';

const systemPrompt = `你是台灣旅遊規劃專家。使用者想替換行程中的一個景點或美食，請推薦 3 個不同的替代選項讓使用者選擇。

重要規則：
1. 只回傳純 JSON，不可加入任何說明文字或 markdown 語法
2. 必須推薦 3 個選項
3. 不可推薦已在行程中的地點
4. type 只能填「景點」或「美食」兩種
5. note 是一句20字以內的中文簡短介紹
6. 推薦的地點要真實存在於該城市
7. 三個選項要有多樣性（例如：景點+美食，或不同風格的景點）

必須嚴格遵守以下輸出格式：
{"suggestions":[{"type":"景點","name":"xxx","note":"xxx"},{"type":"美食","name":"xxx","note":"xxx"},{"type":"景點","name":"xxx","note":"xxx"}]}`;

const userMessage = `目的地：${body.destination}${regionNote}
時段：第 ${body.day} 天${slotLabel}
要替換的地點：${body.replace_spot}
旅遊傾向：${body.preference}
行程中已有的地點（不可重複推薦）：${keepList}

請推薦 3 個適合的替代選項。`;

return [{
  json: {
    model: 'gpt-4o-mini',
    response_format: { type: 'json_object' },
    temperature: 1.0,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userMessage }
    ]
  }
}];

const raw = $input.first().json.choices[0].message.content;
const result = JSON.parse(raw);
return [{ json: result }];
